package com.bank.validation;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;

// Core algorithm: validate balanced brackets using a stack.
public class BracketValidator {

    // Maps each closing bracket to the opening bracket it must match.
    private static final Map<Character, Character> PAIRS = Map.of(
            ')', '(',
            ']', '[',
            '}', '{');

    // Returns true only if every bracket is correctly matched and ordered.
    public boolean validate(String expression) {
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                // Opening bracket: remember it on top of the stack.
                stack.push(c);
            } else if (PAIRS.containsKey(c)) {
                // Closing bracket: the stack must not be empty and the
                // top must be the matching opener.
                if (stack.isEmpty() || stack.pop() != PAIRS.get(c)) {
                    return false;
                }
            }
            // Non-bracket characters (digits, operators) are ignored here.
        }
        // Valid only if nothing was left unclosed.
        return stack.isEmpty();
    }
}
