package com.bank.validation;

import java.util.logging.Logger;

// Service layer: wraps the validator with audit logging for the bank.
public class BracketValidationService {

    private static final Logger log = Logger.getLogger(BracketValidationService.class.getName());
    private final BracketValidator validator;

    public BracketValidationService(BracketValidator validator) {
        this.validator = validator;
    }

    // Validates a financial expression and records the result for audit.
    public boolean validateExpression(String expression) {
        boolean valid = validator.validate(expression);
        if (valid) {
            log.info(() -> "Expression ACCEPTED (balanced): " + expression);
        } else {
            log.warning(() -> "Expression REJECTED (unbalanced): " + expression);
        }
        return valid;
    }
}
