package com.bank.validation;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: validates several banking expression strings.
public class BracketValidationDemo {

    private static final Logger log = Logger.getLogger(BracketValidationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        BracketValidationService service =
                new BracketValidationService(new BracketValidator());

        log.info("National Bank of India — Expression Bracket Validator");

        service.validateExpression("{[(base+fee)*tax]}");  // balanced
        service.validateExpression("{[(base+fee]*tax)}");  // mismatched order
        service.validateExpression("(((");                 // unclosed openers
        service.validateExpression(")(");                  // closer before opener
        service.validateExpression("[]{}()");              // simple balanced
    }
}
